        get("custom-panel").hidden = active !== "custom";
        for (const entry of modes)entry.closest(".ss-upscale-mode").dataset.selected = String(entry.checked);
        const isReady = !loading && !busy && (active === "model" ? installed.includes(model.value) && Boolean(model.value) : active === "saved" ? saved.includes(workflow.value) && Boolean(imageParam.value) : Boolean(graph.value.trim()));
