        if (!characterId) {
            this.characterId = "";
            this.tab.root.replaceChildren(element("div", "ss-empty", "Open a character to edit its visual canon."));
            return;
        }
        if (characterId === this.characterId && this.data) return;
        this.characterId = characterId;
        this.data = null;
